/// CodeSpecs subtree. Everything here is a routine run *against* an existing
/// audit log — reviewing it on a cadence, reporting privileged use from it,
/// watching it for anomalies, producing evidence from it for a regulator.
/// None of it is a declaration a generator can read: the log the routines
/// consume is declared by CE-LG and configured by CE-CF next door.
pub struct ComplianceReporting {
    pub node: som::SomNode,
}

impl ComplianceReporting {
    /// Binds a ComplianceReporting facade to a document and a path.
    pub fn new(doc: som::DocRef, path: String) -> ComplianceReporting {
        ComplianceReporting { node: som::SomNode::new(doc, path) }
    }

    /// Whether this section **type** declares the standard `content` text leaf
    /// (SOM §21) — a **structural** predicate answering "can this section hold
    /// body text?" as a compile-time constant, without probing the document.
    pub fn can_have_content(&self) -> bool {
        true
    }

    pub fn content(&self) -> String {
        self.node.doc().borrow().content_or(&format!("{}/{}", self.node.path(), "content"))
    }

    pub fn set_content(&self, value: &str) {
        let path = format!("{}/{}", self.node.path(), "content");
        self.node.doc().borrow_mut().set_content(&path, value);
    }

    /// Periodic Review Policy.
    pub fn periodic_reviews(&self) -> PeriodicReviewPolicy {
        PeriodicReviewPolicy::new(self.node.doc(), format!("{}/{}", self.node.path(), "periodicReviews"))
    }

    /// Privilege Usage Reporting.
    pub fn privilege_usage_reports(&self) -> PrivilegeUsageReporting {
        PrivilegeUsageReporting::new(self.node.doc(), format!("{}/{}", self.node.path(), "privilegeUsageReports"))
    }

    /// Anomaly Detection Policy.
    pub fn anomaly_detection(&self) -> AnomalyDetectionPolicy {
        AnomalyDetectionPolicy::new(self.node.doc(), format!("{}/{}", self.node.path(), "anomalyDetection"))
    }

    /// Regulatory Audit Support.
    pub fn regulatory_audit_support(&self) -> RegulatoryAuditSupport {
        RegulatoryAuditSupport::new(self.node.doc(), format!("{}/{}", self.node.path(), "regulatoryAuditSupport"))
    }

    // Additional Notes (text).
    // (skipped: notes has no target type)
}

